# Build a Frontend

Connect a browser wallet to Paxeer with React and viem, show PAX balances, and read contracts at a consistent block.

Start with one clear interaction: connect a wallet and display its PAX balance. viem separates public reads from wallet requests, so your page can load chain state before asking for a signature.

## Use the application workspace

The frontend in apps/launchpad/web uses Next.js, React, viem and Wagmi. From the repository root, install the launchpad workspace dependencies and run its web application.

```
cd apps/launchpad
pnpm install
pnpm dev
```

Configure `apps/launchpad/web/.env.local` with `NEXT_PUBLIC_PAXEER_RPC_URL` set to a browser-accessible node root. Next.js exposes `NEXT_PUBLIC_` values to visitors: use a public browser endpoint and keep provider credentials on a server. The launchpad RPC selector gives NEXT_PUBLIC_RPC_URL and NEXT_PUBLIC_RPC_URL_FALLBACK precedence over this value.

## Define Paxeer once

The chain definition in `apps/launchpad/web/src/core/wallet-sdk/client.ts` makes the chain ID and native currency explicit. For `hyperpax_125-1` the endpoint must answer `eth_chainId` with `0x7d` (125). The node mapping in `modules/evm/config/config.go` also defaults unmapped chain names to 125. Check the endpoint and wallet `id` before requesting a signature.

```
import { createPublicClient, defineChain, http } from "viem";
import { getPaxeerRpcUrl } from "@/core/rpc";

const rpcUrl = getPaxeerRpcUrl();
export const paxeer = defineChain({
  id: 125,
  name: "Paxeer X Network",
  nativeCurrency: { name: "PAX", symbol: "PAX", decimals: 18 },
  rpcUrls: { default: { http: [rpcUrl] } },
});
export const publicClient = createPublicClient({
  chain: paxeer,
  transport: http(rpcUrl),
});
```

## Connect and display a balance

Use this example as a client component alongside `apps/launchpad/web/src/core/wallet-sdk/client.ts`. It requests accounts only after a click, adds Paxeer if the wallet does not know the chain, and clears old results whenever the account or network changes.

```
"use client";

import { useEffect, useRef, useState } from "react";
import { createWalletClient, custom, formatEther, type EIP1193Provider } from "viem";
import { paxeerWalletChain as paxeer, getPublicClient } from "@/core/wallet-sdk/client";

const publicClient = getPublicClient();

function injectedProvider() {
  return (window as Window & { ethereum?: EIP1193Provider }).ethereum;
}

export default function App() {
  const [result, setResult] = useState<string>();
  const [error, setError] = useState<string>();
  const [busy, setBusy] = useState(false);
  const requestId = useRef(0);
  const connecting = useRef(false);
  const mounted = useRef(true);
  const selection = useRef<{ account?: string; chainId?: number }>({});

  useEffect(() => {
    mounted.current = true;
    const provider = injectedProvider();
    const reset = () => {
      requestId.current += 1;
      setResult(undefined);
      setError(undefined);
      selection.current = {};
    };
    const accountsChanged = (accounts: string[]) => {
      if (accounts[0]?.toLowerCase() !== selection.current.account) reset();
    };
    const chainChanged = (chainId: string) => {
      if (Number(chainId) !== selection.current.chainId) reset();
    };
    provider?.on("accountsChanged", accountsChanged);
    provider?.on("chainChanged", chainChanged);
    return () => {
      mounted.current = false;
      requestId.current += 1;
      provider?.removeListener("accountsChanged", accountsChanged);
      provider?.removeListener("chainChanged", chainChanged);
    };
  }, []);

  async function connect() {
    if (connecting.current) return;
    connecting.current = true;
    requestId.current += 1;
    setBusy(true);
    setError(undefined);
    setResult(undefined);
    let readId: number | undefined;
    try {
      const provider = injectedProvider();
      if (!provider) throw new Error("Open this page in a wallet browser or install an EVM wallet.");
      if (await publicClient.getChainId() !== 125) throw new Error("RPC endpoint is not Paxeer chain 125.");
      const wallet = createWalletClient({ chain: paxeer, transport: custom(provider) });
      const [requestedAccount] = await wallet.requestAddresses();
      selection.current.account = requestedAccount?.toLowerCase();
      if (await wallet.getChainId() !== 125) {
        try {
          await wallet.switchChain({ id: 125 });
        } catch (cause) {
          const failure = cause as { code?: number; cause?: { code?: number } };
          if (failure.code !== 4902 && failure.cause?.code !== 4902) throw cause;
          await wallet.addChain({ chain: paxeer });
          await wallet.switchChain({ id: 125 });
        }
      }
      if (!mounted.current) return;
      selection.current = { account: requestedAccount?.toLowerCase(), chainId: 125 };
      // Begin the read after the wallet has completed account and chain selection.
      const id = ++requestId.current;
      readId = id;
      const [account] = await wallet.getAddresses();
      if (!account) throw new Error("No wallet account selected.");
      if (await wallet.getChainId() !== 125) throw new Error("Select Paxeer in your wallet.");
      if (id !== requestId.current || !mounted.current) return;
      selection.current = { account: account.toLowerCase(), chainId: 125 };
      const balance = await publicClient.getBalance({ address: account });
      if (id === requestId.current && mounted.current) {
        setResult(account + ": " + formatEther(balance) + " PAX");
      }
    } catch (cause) {
      if (mounted.current && (readId === undefined || readId === requestId.current)) {
        setError(cause instanceof Error ? cause.message : "Wallet request failed.");
      }
    } finally {
      connecting.current = false;
      if (mounted.current) setBusy(false);
    }
  }

  return (
    <main>
      <h1>Paxeer wallet</h1>
      <button onClick={connect} disabled={busy}>{busy ? "Connecting…" : "Connect and read balance"}</button>
      <p role="status">{result}</p>
      {error && <p role="alert">{error}</p>}
    </main>
  );
}
```

Run `pnpm dev` from apps/launchpad, open the web application, and connect an EVM wallet. The initial connection waits for account and network selection before reading. Later selection changes clear the old result and invalidate a read in flight; click again to refresh. This example reads balances without sending a transaction.

## Read a deployed wrapped-token balance

Use the WPAX contract address produced by [Foundry](/foundry) or [Hardhat](/hardhat). The interface comes from `contracts/src/WPAX.sol`; pass the deployment address and account to this example helper.

```
import { getAddress, parseAbi } from "viem";
import { getPublicClient } from "@/core/wallet-sdk/client";

export async function readWrappedBalance(contractAddress: string, owner: string) {
  const publicClient = getPublicClient();
  if (await publicClient.getChainId() !== 125) throw new Error("Unexpected chain");
  const address = getAddress(contractAddress);
  const blockNumber = await publicClient.getBlockNumber();
  const bytecode = await publicClient.getCode({ address, blockNumber });
  if (!bytecode || bytecode === "0x") throw new Error("No contract at this address");
  const balance = await publicClient.readContract({
    address,
    abi: parseAbi(["function balanceOf(address) view returns (uint256)"]),
    functionName: "balanceOf",
    args: [getAddress(owner)],
    blockNumber,
  });
  return { blockNumber, balance };
}
```

## Build a complete transaction experience

- For writes, simulate the exact call with the selected account, request the wallet signature, then wait for the receipt.

- Show separate states for signature requested, submitted, confirmed, and failed. A returned transaction hash means submission, not successful execution.

- Refresh affected queries after a successful receipt and keep the hash available for inspection.

- For ERC-20 amounts, read the token’s decimals and use `parseUnits`/`formatUnits`. Native PAX uses 18 decimals; arbitrary tokens may differ.

- On mobile, support an in-wallet browser or add a wallet connector that supports your application’s target devices.

For a larger React application, Wagmi adds connector lifecycle and query hooks on top of viem. Retain the same custom Paxeer chain definition and separate public reads from wallet requests.

References: [viem custom chains](https://viem.sh/docs/chains/introduction), [clients and transports](https://viem.sh/docs/clients/intro), and [contract reads](https://viem.sh/docs/contract/readContract).

**Paxeer source:** `apps/launchpad/web/src/core/wallet-sdk/client.ts`, apps/launchpad/web/src/core/rpc.ts, modules/evm/config/config.go (ChainIDMapping), and rpc/state.go (GetBalance and GetCode).

# Build with Hardhat

Use the repository's Hardhat 2 project to compile contracts and interact with a development node.

The contract project at `contracts/` uses Hardhat 2 and a CommonJS configuration. Its sources live under `contracts/src/`. Paxeer EVM chain ID is `125`, mapped from `hyperpax_125-1` in `modules/evm/config/config.go`.

## Use the in-tree project

Use a [Node.js version supported by Hardhat 2](https://hardhat.org/hardhat2). Install the dependencies recorded in `contracts/package-lock.json` and inspect the local tool version.

```
cd contracts
npm ci
npx hardhat --version
```

`contracts/package.json` declares `hardhat ^2.20.1`, `@nomicfoundation/hardhat-toolbox ^6.1.2`, and `@openzeppelin/hardhat-upgrades ^3.0.2`. The lockfile records the resolved dependency versions.

## Configure the development endpoint

`contracts/hardhat.config.js` selects Solidity `0.8.27`, the `prague` target, and an enabled optimizer with `1000` runs. Its network configuration reads `PAXEER_LOCAL_EVM_RPC_URL`. The following excerpt shows the compiler and source settings.

```
module.exports = {
  solidity: {
    version: "0.8.27",
    settings: {
      evmVersion: "prague",
      optimizer: { enabled: true, runs: 1000 },
    },
  },
  paths: { sources: "./src" },
};
```

The configured HTTP network is named `paxlocal`. Set `PAXEER_LOCAL_EVM_RPC_URL` to your development node's root EVM endpoint before connecting. The default uses the loopback interface on port `8545`.

The configuration loads `contracts/.env` through `dotenv` and reads the endpoint from the environment. The following command requires that endpoint to be set.

```
: "${PAXEER_LOCAL_EVM_RPC_URL:?Set the development node EVM endpoint}"
```

## Read sources and run the compiler check

`contracts/src/Box.sol` is an existing storage example. It exposes `store`, `retrieve`, and `boxIncr` and emits `ValueChanged`.

```
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Box {
    uint256 private _value;

    event ValueChanged(uint256 value);

    function store(uint256 value) public {
        _value = value;
        emit ValueChanged(value);
    }

    function retrieve() public view returns (uint256) {
        return _value;
    }

    function boxIncr() public {
        _value = _value + 1;
        emit ValueChanged(_value);
    }
}
```

Token contracts use the installed OpenZeppelin package. For example, this is the import and constructor in `contracts/src/TestToken.sol`.

```
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract TestToken is ERC20, Ownable {
    constructor(string memory name, string memory symbol) Ownable(msg.sender) ERC20(name, symbol) {
        _mint(msg.sender, 1000 * (10 ** uint256(decimals())));
    }

    // The owner adjusts balances by minting or burning
    function setBalance(address account, uint256 amount) public onlyOwner {
        uint256 currentBalance = balanceOf(account);
        if (amount > currentBalance) {
            _mint(account, amount - currentBalance);
        } else if (amount < currentBalance) {
            _burn(account, currentBalance - amount);
        }
    }
}
```

```
npx hardhat compile
node --test test/hardhat_solc_parity.test.js
```

The focused Node test `contracts/test/hardhat_solc_parity.test.js` checks that the Hardhat compiler version matches `foundry.paxeer.toml`. Run it from `contracts/` after compiling.

## Interact through the console

In the Hardhat console, the following Ethers calls deploy the existing Box artifact, wait for deployment, write a value, and read it. Deployment and writes require a signer exposed by the development node.

```
const box = await ethers.deployContract("Box");
await box.waitForDeployment();
const tx = await box.store(7);
const receipt = await tx.wait();
await box.retrieve();
```

Open the console with the configured network. Confirm that it is the intended development node before running the deployment expressions above.

```
npx hardhat console --network paxlocal
```

## Check the connected chain

In that console, inspect the endpoint's chain ID before submitting transactions. Paxeer uses `125`. Deployment and storage writes spend the configured signer's gas balance.

```
const network = await ethers.provider.getNetwork();
network.chainId;
```

Retain the contract address, transaction receipt, source, and compiler settings. Read the result through the [querying guide](/querying-evm). Hardhat writes the Box artifact to `contracts/artifacts/src/Box.sol/Box.json`.

`contracts/package.json` declares `@openzeppelin/contracts ^5.4.0`. Its `TestToken` source imports `@openzeppelin/contracts/token/ERC20/ERC20.sol`.

References: [Hardhat 2 configuration](https://hardhat.org/hardhat2/hardhat-runner/docs/config), [contract tests](https://hardhat.org/hardhat2/hardhat-runner/docs/guides/test-contracts), and [contract deployment](https://hardhat.org/hardhat2/hardhat-runner/docs/guides/deploying).

**Paxeer source:** `contracts/hardhat.config.js`, `contracts/package.json`, `contracts/src/Box.sol`, `contracts/src/TestToken.sol`, and `contracts/test/hardhat_solc_parity.test.js`.

# Query the EVM

Read Paxeer balances, contract state, receipts, and bounded event ranges with JSON-RPC, Cast, and viem.

Read-only queries work without a signer or a PAX balance. Choose an EVM JSON-RPC endpoint, confirm its network, and record the block number when several reads must describe the same state.

## Verify the endpoint

Set `PAXEER_RPC_URL` to your EVM endpoint. For `hyperpax_125-1` the result of this request must be `0x7d`, which is decimal 125. The node defaults unmapped chain identifiers to 125 as well. Confirm the intended genesis and network independently; a matching numeric chain ID alone does not distinguish deployments.

```
: "${PAXEER_RPC_URL:?Set your Paxeer EVM RPC URL}"
curl --fail-with-body --silent --show-error "$PAXEER_RPC_URL"   -H 'Content-Type: application/json'   --data '{"jsonrpc":"2.0","id":1,"method":"eth_chainId","params":[]}'
```

HTTP 200 can still contain a JSON-RPC `error`. Check both the HTTP result and the response body. The consensus RPC server exposes routes such as `/status`; it is not interchangeable with the EVM JSON-RPC listener.

## Inspect accounts and contracts with Cast

Set `ACCOUNT_ADDRESS` and `CONTRACT_ADDRESS` to addresses from your application or deployment records. The contract example assumes an ERC-20 token implementing `balanceOf` and `transfer`. Use its published ABI to encode and decode calls.

```
cast block-number --rpc-url "$PAXEER_RPC_URL"
cast balance "$ACCOUNT_ADDRESS" --rpc-url "$PAXEER_RPC_URL"
cast nonce "$ACCOUNT_ADDRESS" --rpc-url "$PAXEER_RPC_URL"
cast code "$CONTRACT_ADDRESS" --rpc-url "$PAXEER_RPC_URL"
cast call "$CONTRACT_ADDRESS" 'balanceOf(address)(uint256)' "$ACCOUNT_ADDRESS"   --rpc-url "$PAXEER_RPC_URL"
cast calldata 'transfer(address,uint256)' "$ACCOUNT_ADDRESS" 42
```

The final command only encodes calldata. It does not submit a transaction. `cast balance` returns native base units by default. A missing contract, wrong ABI, or unavailable historical state can make a read fail even when the RPC endpoint is healthy.

## Read token data at one block

Install `viem` in your Node project with `npm install viem` and save this example as `read-token.mjs`. The repository’s wallet client also declares viem in `apps/wallet/package.json`. Set `TOKEN_ADDRESS` and `ACCOUNT_ADDRESS` to the EVM addresses you want to query, then run `node read-token.mjs`.

```
import { createPublicClient, formatUnits, getAddress, http, parseAbi } from "viem";

const rpcUrl = process.env.PAXEER_RPC_URL;
if (!rpcUrl) throw new Error("Set PAXEER_RPC_URL");
const token = getAddress(process.env.TOKEN_ADDRESS ?? "");
const account = getAddress(process.env.ACCOUNT_ADDRESS ?? "");
const client = createPublicClient({ transport: http(rpcUrl) });
if (await client.getChainId() !== 125) throw new Error("Unexpected chain ID");

const blockNumber = await client.getBlockNumber();
const abi = parseAbi([
  "function decimals() view returns (uint8)",
  "function symbol() view returns (string)",
  "function balanceOf(address owner) view returns (uint256)",
]);
const [decimals, symbol, balance] = await Promise.all([
  client.readContract({ address: token, abi, functionName: "decimals", blockNumber }),
  client.readContract({ address: token, abi, functionName: "symbol", blockNumber }),
  client.readContract({ address: token, abi, functionName: "balanceOf", args: [account], blockNumber }),
]);
console.log({ block: blockNumber.toString(), symbol, balance: formatUnits(balance, decimals) });
```

The requests run concurrently at the same block using ordinary contract calls. For tokens with a custom metadata interface, replace the example ABI with the contract’s published ABI.

## Fetch events in bounded ranges

Save the following as `read-transfers.mjs`. Provide the token address, RPC URL, and an inclusive `FROM_BLOCK`/`TO_BLOCK` range. Start at the contract’s deployment block when building a full history.

```
import { createPublicClient, getAddress, http, parseAbiItem } from "viem";

const rpcUrl = process.env.PAXEER_RPC_URL;
if (!rpcUrl || !process.env.FROM_BLOCK || !process.env.TO_BLOCK) {
  throw new Error("Set PAXEER_RPC_URL, FROM_BLOCK and TO_BLOCK");
}
const address = getAddress(process.env.TOKEN_ADDRESS ?? "");
const client = createPublicClient({ transport: http(rpcUrl) });
if (await client.getChainId() !== 125) throw new Error("Unexpected chain ID");
const first = BigInt(process.env.FROM_BLOCK);
const last = BigInt(process.env.TO_BLOCK);
if (first < 0n || last < first) throw new Error("Invalid block range");
const event = parseAbiItem("event Transfer(address indexed from, address indexed to, uint256 value)");
const chunkSize = 500n;

for (let fromBlock = first; fromBlock <= last; fromBlock += chunkSize) {
  const toBlock = fromBlock + chunkSize - 1n < last ? fromBlock + chunkSize - 1n : last;
  const logs = await client.getLogs({ address, event, fromBlock, toBlock, strict: true });
  for (const log of logs) {
    console.log(JSON.stringify(log, (_, value) => typeof value === "bigint" ? value.toString() : value));
  }
}
```

Start with 500-block chunks and reduce the size if your provider returns a range or result-limit error. The node's default maximum `eth_getLogs` range is 2000 blocks, so 500-block chunks stay within it unless an operator configures a lower limit. A production indexer should commit processed logs and its cursor together, resume only after successful chunks, and deduplicate by chain ID, block hash, transaction hash, and log index.

## Keep transaction views consistent

`eth_` methods provide the EVM view and exclude shell receipts and bank transfers. The `pax_` namespace additionally includes shell receipts, and `pax2_` additionally includes bank transfers, so the same block can list different transactions and indices per namespace; availability is configured by the node. Keep one namespace throughout an indexer and use hashes for lookup. See [JSON-RPC namespaces](/json-rpc).

For historical reads, the provider must retain state at that height. A recent balance read can work while an older `eth_call` fails. Inspect the receipt’s `status` for success or a revert. Open-block receipts can precede commitment; require `pax_sequencerReceipt` to report `committed` when finality is required.

References: [viem contract reads](https://viem.sh/docs/contract/readContract), [event logs](https://viem.sh/docs/actions/public/getLogs), and [Ethereum JSON-RPC](https://ethereum.org/en/developers/docs/apis/json-rpc/).

**Paxeer source:** `rpc/state.go` (StateAPI), `rpc/filter.go` (FilterAPI), `rpc/tx.go` (TransactionAPI), and `rpc/config/config.go` (query limits).

# SDK quickstarts

Register a principal, fund an account, submit a signed transaction, and verify execution evidence with the Paxeer X SDKs.

## Register, fund, send, verify

Choose a node transaction flow or a Human payment journey before selecting a client. `eth_sendRawTransaction` submits signed EVM transactions to the node; `px_register` creates a principal binding through the hosted gateway. Retrieve progress with `pax_sequencerReceipt` and trusted signing-key data with `px_getReceiptKeys`. Faucet funding requires an authorized identity session.

## Rust

Use `RpcClient` for node access and hosted registration. Sign the digest from `register::binding` before registering. Node connections use `RpcClient::connect_node`; `RpcClient::get_balance` reads an EVM balance, and `RpcClient::send_raw_transaction` submits signed transaction bytes.

### Registration binding

```
use layerx_sdk::register::{binding, TENANT};
use layerx_sdk::rpc::{RpcClient, RpcError};

fn registration_digest(public_key: &[u8; 32]) -> [u8; 32] {
    binding(TENANT, public_key)
}

fn register(rpc: &RpcClient, public_key: [u8; 32], signature: &[u8; 64])
    -> Result<layerx_sdk::register::Registration, RpcError>
{
    rpc.register(public_key, signature)
}
```

### Read an EVM balance

```
use layerx_sdk::rpc::{RpcClient, RpcError};

fn balance(rpc: &RpcClient, address: &str) -> Result<serde_json::Value, RpcError> {
    rpc.get_balance(address)
}
```

### Submit a signed EVM transaction

```
use layerx_sdk::rpc::{RpcClient, RpcError};

fn send(rpc: &RpcClient, raw: &[u8]) -> Result<[u8; 32], RpcError> {
    rpc.send_raw_transaction(raw)
}
```

### Connect to a node

```
use layerx_sdk::rpc::{RpcClient, RpcError};

fn connect(endpoint: &str) -> Result<RpcClient, RpcError> {
    RpcClient::connect_node(endpoint, None)
}
```

The Rust committed-wait example uses a caller-supplied receipt policy. Configure the client with a runtime clock and independently pinned node consensus authority before waiting for committed inclusion.

### Verify committed inclusion (Rust)

```
use std::time::Duration;
use layerx_sdk::rpc::{Commitment, RpcClient, RpcError};
use layerx_sdk::rpc_verification::{ReceiptPolicy, VerifiedRpcReceipt};

fn wait_for_commit(
    rpc: &RpcClient,
    transaction_hash: [u8; 32],
    policy: &ReceiptPolicy,
) -> Result<VerifiedRpcReceipt, RpcError> {
    rpc.wait_for(transaction_hash, Commitment::Committed, policy, Duration::from_secs(30))
}
```

## TypeScript

Use `JsonRpcClient` for node reads and signed EVM transaction submission. `ProductionClient` provides Human operations through a configured Human transport. Registration and faucet calls use the hosted gateway contract.

### Connect and submit a transaction

```
import { JsonRpcClient } from "@sidiora/layerx-sdk";

export function openNode(endpoint: string): JsonRpcClient {
  return new JsonRpcClient(endpoint);
}

export function send(rpc: JsonRpcClient, signedTransaction: Uint8Array): Promise<string> {
  return rpc.sendRawTransaction(signedTransaction);
}
```

### Quote and commit a Human payment

```
import { ProductionClient, idempotencyKey } from "@sidiora/layerx-sdk";

type MoveRequest = {
  source: string;
  destination: string;
  money: { amount: string; currency: string };
};

export async function pay(
  client: ProductionClient,
  request: MoveRequest,
  paymentKey: string,
): Promise<Record<string, unknown>> {
  const quote = await client.human<MoveRequest, { quote_id: string }>("move.quote", request);
  return client.human<{ quote_id: string }, Record<string, unknown>>(
    "move.commit",
    { quote_id: quote.quote_id },
    { idempotencyKey: idempotencyKey(paymentKey) },
  );
}
```

### Verify canonical receipt bytes

```
import { verifySequencerReceipt } from "@sidiora/layerx-sdk";
import type { SequencerReceiptKey, SequencerReceiptVerification } from "@sidiora/layerx-sdk";

export function verify(
  signedReceipt: Uint8Array,
  rawTransaction: Uint8Array,
  receiptKeys: readonly SequencerReceiptKey[],
): Promise<SequencerReceiptVerification> {
  return verifySequencerReceipt(signedReceipt, rawTransaction, receiptKeys);
}
```

## Python

`PaymentRpc` sends node methods at the root path `/`. The hosted gateway client handles registration and faucet methods at its configured service endpoint. Registration takes lowercase hexadecimal keys and signatures; funding requires a Bearer identity session.

### Hosted registration

```
from layerx_sdk.x402_rpc import HostedGatewayRpc

def register(rpc: HostedGatewayRpc, signer_public_key: str, registration_signature: str) -> dict:
    result = rpc.call("px_register", [signer_public_key, registration_signature])
    if not isinstance(result, dict):
        raise ValueError("Invalid registration response")
    return result
```

### Authenticated funding

```
from layerx_sdk.x402_rpc import HostedGatewayRpc

def request_funds(gateway_endpoint: str, session_token: str, did: str, signer_public_key: str) -> dict:
    rpc = HostedGatewayRpc(gateway_endpoint, {"Authorization": f"Bearer {session_token}"})
    result = rpc.call("px_requestFunds", [did, signer_public_key])
    if not isinstance(result, dict):
        raise ValueError("Invalid funding response")
    return result
```

### Submit a signed EVM transaction

```
from layerx_sdk import PaymentRpc

def send(rpc: PaymentRpc, raw_transaction: str) -> str:
    return rpc.send(raw_transaction)
```

### Quote and commit a Human payment

```
from layerx_sdk import IdempotencyKey, ProductionClient

def pay(layerx: ProductionClient, source, destination, money, payment_key):
    quote = layerx.human("move.quote", {"source": source, "destination": destination, "money": money})
    return layerx.human("move.commit", {"quote_id": quote["quote_id"]}, idempotency_key=IdempotencyKey(payment_key))
```

### Verify canonical receipt bytes

```
from layerx_sdk import ReceiptKey, SequencerReceiptVerification, verify_sequencer_receipt

def verify(
    signed_receipt: bytes,
    raw_transaction: bytes,
    receipt_keys: tuple[ReceiptKey, ...],
) -> SequencerReceiptVerification:
    return verify_sequencer_receipt(signed_receipt, raw_transaction, receipt_keys)
```

## Go

Use `NewHumanHTTPTransport` and `Client.Human` for a quote followed by an idempotent commit. The Go package is in sdk/platform/go; its import path is declared by that directory's go.mod.

### Quote and commit a Human payment

```
package main

import (
	"context"
	"net/http"

	layerx "github.com/Sidiora-Labs/LayerX-Network/sdk/platform/go"
)

type Money struct {
	Amount   string `json:"amount"`
	Currency string `json:"currency"`
}

type MoveQuoteRequest struct {
	Source      string `json:"source"`
	Destination string `json:"destination"`
	Money       Money  `json:"money"`
}

type MoveQuote struct {
	QuoteID string `json:"quote_id"`
}

type MoveCommitRequest struct {
	QuoteID string `json:"quote_id"`
}

type Journey struct {
	JourneyID string `json:"journey_id"`
	State     string `json:"state"`
}

func pay(ctx context.Context, apiURL, apiToken, source, destination, paymentKey string, money Money) (Journey, error) {
	authorize := func(request *http.Request) error {
		request.Header.Set("Authorization", "Bearer "+apiToken)
		return nil
	}
	transport, err := layerx.NewHumanHTTPTransport(apiURL, nil, authorize)
	if err != nil {
		return Journey{}, err
	}
	client, err := layerx.NewClient(transport, nil)
	if err != nil {
		return Journey{}, err
	}
	key, err := layerx.NewIdempotencyKey(paymentKey)
	if err != nil {
		return Journey{}, err
	}
	var quote MoveQuote
	if err := client.Human(ctx, layerx.HumanOperationMoveQuote, MoveQuoteRequest{Source: source, Destination: destination, Money: money}, &quote, layerx.CallOptions{}); err != nil {
		return Journey{}, err
	}
	var journey Journey
	if err := client.Human(ctx, layerx.HumanOperationMoveCommit, MoveCommitRequest{QuoteID: quote.QuoteID}, &journey, layerx.CallOptions{IdempotencyKey: key}); err != nil {
		return Journey{}, err
	}
	return journey, nil
}
```

